import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.D9E58p8B.js";const g=JSON.parse('{"title":"Déléguer à un sous-agent","description":"","frontmatter":{"title":"Déléguer à un sous-agent"},"headers":[],"relativePath":"agent/deleguer.md","filePath":"agent/deleguer.md"}'),o={name:"agent/deleguer.md"};function l(u,e,i,s,c,p){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="deleguer-a-un-sous-agent" tabindex="-1">Déléguer à un sous-agent <a class="header-anchor" href="#deleguer-a-un-sous-agent" aria-label="Permalink to &quot;Déléguer à un sous-agent&quot;">​</a></h1><p>Un enchaînement d&#39;actions sur une interface (regarder, agir, relire, recommencer) remplit vite le contexte d&#39;un agent avec des captures. Il vaut mieux le confier à un sous-agent, qui ne renvoie que le résultat.</p><h2 id="ce-que-vous-demandez" tabindex="-1">Ce que vous demandez <a class="header-anchor" href="#ce-que-vous-demandez" aria-label="Permalink to &quot;Ce que vous demandez&quot;">​</a></h2><blockquote><p>« Relève le numéro de version affiché dans la fenêtre À propos de l&#39;application. »</p></blockquote><h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><ol><li>Il appelle <a href="/Daimon/reference/vue.html#vue-pilot-brief"><code>vue_pilot_brief</code></a> avec l&#39;objectif. L&#39;outil ne fait appel à aucune IA : il rend une <strong>porte go/no-go</strong> et un <strong>prompt prêt à coller</strong> pour un sous-agent.</li><li>Si la porte est prête, il lance le sous-agent avec ce prompt. Les captures restent dans le sous-agent ; seul le texte extrait remonte.</li><li>Si la porte n&#39;est pas prête, il <strong>calibre d&#39;abord</strong> avec <a href="/Daimon/reference/vue.html#vue-calibrate"><code>vue_calibrate</code></a>, qui fige la topologie des écrans sous un nom, plutôt que de piloter à l&#39;aveugle.</li></ol><p>Deux outils complètent le brief :</p><ul><li><a href="/Daimon/reference/vue.html#vue-profile"><code>vue_profile</code></a> dit si la topologie d&#39;écrans actuelle correspond à un profil connu ;</li><li><a href="/Daimon/reference/vue.html#vue-profile-brief"><code>vue_profile_brief</code></a> produit l&#39;amorce d&#39;un sous-agent : porte d&#39;appariement du profil et indices d&#39;écrans adressables.</li></ul><h2 id="ce-que-vous-obtenez" tabindex="-1">Ce que vous obtenez <a class="header-anchor" href="#ce-que-vous-obtenez" aria-label="Permalink to &quot;Ce que vous obtenez&quot;">​</a></h2><p>Le résultat de la tâche, sans la pile de captures intermédiaires.</p><h2 id="ce-qui-ne-change-pas" tabindex="-1">Ce qui ne change pas <a class="header-anchor" href="#ce-qui-ne-change-pas" aria-label="Permalink to &quot;Ce qui ne change pas&quot;">​</a></h2><p>Le sous-agent travaille sous <strong>le même plafond</strong> que l&#39;agent principal : il ne peut pas faire plus. Les exclusions, la censure et le journal d&#39;audit s&#39;appliquent à lui comme à n&#39;importe quel client.</p><p>Suite : <a href="/Daimon/agent/diagnostiquer.html">Quand ça ne marche pas</a>.</p>',13)])])}const m=a(o,[["render",l]]);export{g as __pageData,m as default};
